// Histc op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_triple_chevrons_func.h"

namespace ascend_kernel {

at::Tensor histc(const at::Tensor &x, int64_t bins, int64_t minVal, int64_t maxVal)
{
    TORCH_CHECK(x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
                    x.scalar_type() == at::kBFloat16,
                "x must be float32, float16, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(bins > 0, "bins must be a positive integer");

    int32_t binsVal = static_cast<int32_t>(bins);
    float minValF = static_cast<float>(minVal);
    float maxValF = static_cast<float>(maxVal);

    int32_t numel = static_cast<int32_t>(x.numel());
    if (numel == 0 || binsVal <= 0) {
        return at::zeros({binsVal}, x.options().dtype(at::kInt));
    }

    // Get core count from platform API (pure Vector → AIV)
    int32_t aivCoreNum = static_cast<int32_t>(
        platform_ascendc::PlatformAscendCManager::GetInstance()->GetCoreNumAiv());
    if (aivCoreNum <= 0) { aivCoreNum = 20; }

    int32_t usedCoreNum = std::min<int32_t>(aivCoreNum, std::max<int32_t>(1, numel));
    int32_t chunkSize = (numel + usedCoreNum - 1) / usedCoreNum;
    int32_t maxNumTiles = (chunkSize + 256 - 1) / 256;

    // Bin index computation scale factors
    float invBw = static_cast<float>(binsVal) / (maxValF - minValF);
    float minValParam = minValF;
    float maxValParam = maxValF;

    // Output: (usedCoreNum, bins) int32 elements — 2D for easy host accumulation
    at::Tensor output = at::empty({usedCoreNum, binsVal},
                                  x.options().dtype(at::kInt));

    // dtype flag: 0=float32, 1=float16, 2=bfloat16
    int64_t dtypeFlag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All tiling params as left values for EXEC_KERNEL_CMD
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    uint32_t numelLv = static_cast<uint32_t>(numel);
    uint32_t binsLv = static_cast<uint32_t>(binsVal);
    uint32_t chunkSizeLv = static_cast<uint32_t>(chunkSize);
    uint32_t maxNumTilesLv = static_cast<uint32_t>(maxNumTiles);
    float invBwLv = invBw;
    float minValLv = minValParam;
    float maxValLv = maxValParam;

    if (dtypeFlag == 0) {
        EXEC_KERNEL_CMD(histc_float, blockDim, x, output,
                        numelLv, binsLv, chunkSizeLv, maxNumTilesLv,
                        invBwLv, minValLv, maxValLv);
    } else if (dtypeFlag == 1) {
        EXEC_KERNEL_CMD(histc_half, blockDim, x, output,
                        numelLv, binsLv, chunkSizeLv, maxNumTilesLv,
                        invBwLv, minValLv, maxValLv);
    } else {
        EXEC_KERNEL_CMD(histc_bfloat16, blockDim, x, output,
                        numelLv, binsLv, chunkSizeLv, maxNumTilesLv,
                        invBwLv, minValLv, maxValLv);
    }

    // Accumulate per-core histograms across dim=0
    // output shape is (usedCoreNum, bins); sum gives (bins,)
    at::Tensor result = at::sum(output, 0);
    // torch.histc returns int64; cast to match
    return result.to(at::kLong);
}

