45	template <typename T>
46	__aicore__ inline void KernelHistc<T>::Init(
47	    __gm__ T *xGm,
48	    __gm__ int32_t *outputGm,
49	    uint32_t numel,
50	    uint32_t bins,
51	    uint32_t chunkSize,
52	    uint32_t maxNumTiles,
53	    float invBw,
54	    float minVal)
55	{
56	    xGm_.SetGlobalBuffer(xGm);
57	    outputGm_.SetGlobalBuffer(outputGm);
58	    numel_ = numel;
59	    bins_ = bins;
60	    chunkSize_ = chunkSize;
61	    maxNumTiles_ = maxNumTiles;
62	    invBw_ = invBw;
63	    minVal_ = minVal;
64	
65	    uint32_t histBytes = bins_ * sizeof(int32_t);
66	    pipe_.InitBuffer(histBuf_, histBytes);
67	    uint32_t tileBytes = TILE_SIZE * sizeof(T);
68	    pipe_.InitBuffer(tileBuf_, tileBytes);
69	    if constexpr (!std::is_same_v<T, float>) {
70	        uint32_t castBytes = TILE_SIZE * sizeof(float);
71	        pipe_.InitBuffer(castBuf_, castBytes);
72	    }
73	}
