75	template <typename T>
76	__aicore__ inline void KernelHistc<T>::Process()
77	{
78	    uint32_t cid = AscendC::GetBlockIdx();
79	    start_ = cid * chunkSize_;
80	    end_ = start_ + chunkSize_;
81	    if (end_ > numel_) { end_ = numel_; }
82	
83	    AscendC::LocalTensor<int32_t> localHist = histBuf_.Get<int32_t>();
84	    AscendC::LocalTensor<T> tileData = tileBuf_.Get<T>();
85	    AscendC::LocalTensor<float> tileF32;
86	
87	    // Zero-initialize histogram
88	    AscendC::Duplicate(localHist, static_cast<int32_t>(0), bins_);
89	
90	    if constexpr (!std::is_same_v<T, float>) {
91	        tileF32 = castBuf_.Get<float>();
92	    }
93	
94	    uint32_t tIdx = 0;
95	    while (tIdx < maxNumTiles_) {
96	        uint32_t tileStart = start_ + tIdx * TILE_SIZE;
97	        uint32_t tileLen = end_ - tileStart;
98	        if (tileLen > TILE_SIZE) { tileLen = TILE_SIZE; }
99	        if (tileLen == 0) {
100	            tIdx++;
101	            continue;
102	        }
103	
104	        // CopyIn: GM -> UB via DataCopyPad
105	        AscendC::DataCopyExtParams copyParams{
106	            1,
107	            tileLen * static_cast<uint32_t>(sizeof(T)),
108	            0, 0, 0
109	        };
110	        AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
111	        AscendC::DataCopyPad(tileData, xGm_[tileStart], copyParams, padParams);
112	        AscendC::PipeBarrier<PIPE_MTE2>();
113	
114	        // Prepare float32 tile
115	        if constexpr (std::is_same_v<T, float>) {
116	            tileF32 = tileData.template ReinterpretCast<float>();
117	        } else {
118	            AscendC::Cast(tileF32, tileData, AscendC::RoundMode::CAST_NONE, tileLen);
119	            AscendC::PipeBarrier<PIPE_V>();
120	        }
121	
122	        // Element-by-element: compute bin index and update histogram
123	        for (uint32_t i = 0; i < tileLen; i++) {
124	            float val = tileF32.GetValue(i);
125	            if (val >= minVal_ && val <= (minVal_ + 1.0f / invBw_)) {
126	                float xNorm = (val - minVal_) * invBw_;
127	                int32_t binIdx = static_cast<int32_t>(xNorm);
128	                if (binIdx < 0) { binIdx = 0; }
129	                if (binIdx >= static_cast<int32_t>(bins_)) { binIdx = static_cast<int32_t>(bins_) - 1; }
130	                localHist.SetValue(binIdx, localHist.GetValue(binIdx) + 1);
131	            }
132	        }
133	
134	        tIdx++;
135	    }
136	
137	    // CopyOut: write histogram to output at cid * bins
138	    AscendC::DataCopyExtParams copyOutParams{
139	        1,
140	        bins_ * static_cast<uint32_t>(sizeof(int32_t)),
141	        0, 0, 0
142	    };
143	    AscendC::DataCopyPad(outputGm_[cid * bins_], localHist, copyOutParams);
144	}
